{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C26"],
      "claim": "Prednisolone, the closest structural analogue, has systemic availability of 72 ± 10% after oral administration in humans, directly supporting high oral bioavailability for the query corticosteroid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Deflazacort, a corticosteroid analogue with 68% absolute oral bioavailability, supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Methylprednisolone tablets show absolute bioavailability of 0.82 ± 0.11 in normal subjects, supporting high oral bioavailability for the structurally related query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Hydrocortisone has essentially complete absolute oral bioavailability (mean 1.00, 95% CI 0.89–1.14), supporting high F for the query steroid core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Dexamethasone shows oral bioavailability of 81.4 ± 15.8% in humans, supporting high F for the query despite added acetal substitution.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Loteprednol etabonate has very low oral bioavailability, but this is a less transferable ester prodrug analogue lacking the free 21-hydroxy and acetal features of the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C49"],
      "claim": "Mometasone has <1% oral bioavailability, but it is a halogenated ester-containing corticosteroid with much lower similarity to the query, so it carries limited weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest and most transferable experimental analogues are non-halogenated corticosteroids with free 21-hydroxy groups, all showing oral bioavailability well above 20%. The low-bioavailability analogues are less similar and contain ester or halogen motifs absent in the query. Therefore, high oral bioavailability (F ≥ 20%) is better supported.",
  "evidence_gaps": [
    "No direct oral bioavailability data for the query itself or for the desisobutyryl-ciclesonide-like 16,17-cyclohexyl acetal corticosteroid class.",
    "Potential first-pass metabolism of 16,17-acetal corticosteroids (e.g., budesonide-like compounds) could lower F, but no direct evidence is available for this exact scaffold.",
    "Human oral bioavailability of the active metabolite of ciclesonide is not directly represented in the retrieved evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

